ppraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Snow Load & Roof Collapse Appraisal","url":"https://wisconsininsuranceappraiser.com/appraisal-solutions/snow-load-roof-collapse-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Sewer Backup Appraisal","url":"https://wisconsininsuranceappraiser.com/appraisal-solutions/water-sewer-backup-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://wisconsininsuranceappraiser.com/appraisal-solutions/fire-smoke-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dam & Frozen Pipe Appraisal","url":"https://wisconsininsuranceappraiser.com/appraisal-solutions/ice-dam-frozen-pipe-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Farm, Barn & Outbuilding Appraisal","url":"https://wisconsininsuranceappraiser.com/appraisal-solutions/farm-barn-outbuilding-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Carrier Estimate Review","url":"https://wisconsininsuranceappraiser.com/appraisal-solutions/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services & Selection","url":"https://wisconsininsuranceappraiser.com/appraisal-solutions/umpire-selection-services/"}}]},"description":"Independent insurance appraisal, estimate review and umpire services for disputed property claims in all 72 Wisconsin counties.","areaServed":[{"@type":"State","name":"Wisconsin"},{"@type":"City","name":"Milwaukee"},{"@type":"City","name":"Madison"},{"@type":"City","name":"Green Bay"},{"@type":"City","name":"Kenosha"},{"@type":"City","name":"Racine"},{"@type":"City","name":"Appleton"},{"@type":"City","name":"Waukesha"},{"@type":"City","name":"Eau Claire"},{"@type":"City","name":"Oshkosh"},{"@type":"City","name":"Janesville"},{"@type":"City","name":"La Crosse"},{"@type":"City","name":"Wausau"}],"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Hail damage","Ice dams","Snow load","Wind damage"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://wisconsininsuranceappraiser.com/#website","url":"https://wisconsininsuranceappraiser.com/","name":"Wisconsin Insurance Appraiser","publisher":{"@id":"https://wisconsininsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://wisconsininsuranceappraiser.com/claims-dictionary/#webpage","url":"https://wisconsininsuranceappraiser.com/claims-dictionary/","name":"Insurance Claims Dictionary | ACV, RCV, Umpire & More","description":"Searchable plain-English dictionary of property insurance claim terms: actual cash value, holdback, ice dam, umpire, matching, O&P and more.","inLanguage":"en-US","isPartOf":{"@id":"https://wisconsininsuranceappraiser.com/#website"},"about":{"@id":"https://wisconsininsuranceappraiser.com/#business"},"publisher":{"@id":"https://wisconsininsuranceappraiser.com/#business"},"dateModified":"2026-11-13","primaryImageOfPage":{"@type":"ImageObject","url":"https://wisconsininsuranceappraiser.com/assets/img/photos/paperwork.webp","width":1024,"height":680},"breadcrumb":{"@id":"https://wisconsininsuranceappraiser.com/claims-dictionary/#breadcrumb"},"mainEntity":{"@id":"https://wisconsininsuranceappraiser.com/claims-dictionary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://wisconsininsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claims dictionary","item":"https://wisconsininsuranceappraiser.com/claims-dictionary/"}],"@id":"https://wisconsininsuranceappraiser.com/claims-dictionary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Property insurance claims dictionary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value","description":"The value of damaged property at the time of loss, usually figured as replacement cost minus depreciation. Some policies define it differently."},{"@type":"DefinedTerm","name":"Additional living expense","description":"Coverage for the extra cost of living elsewhere while a home can’t be lived in after a covered loss, subject to policy limits."},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of a covered loss. It is the question an appraisal panel is normally asked to decide."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision that sets the amount of loss, generally binding once signed by two of the three panel members."},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy provision that lets either party demand appraisal when they disagree on the amount of loss and sets out how the process works."},{"@type":"DefinedTerm","name":"Appraisal demand","description":"The written notice from one party invoking the appraisal clause, usually naming that party’s appraiser."},{"@type":"DefinedTerm","name":"Coinsurance","description":"A policy condition that can reduce a claim payment if the property was insured for less than a required percentage of its value. More common on commercial policies."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing the insured, property, coverages, limits, deductibles and endorsements."},{"@type":"DefinedTerm","name":"Deductible","description":"The portion of a covered loss the policyholder pays before the insurer’s payment begins."},{"@type":"DefinedTerm","name":"Depreciation","description":"A reduction in value for age, wear and condition, subtracted from replacement cost to reach actual cash value."},{"@type":"DefinedTerm","name":"Derecho","description":"A long-lived, widespread windstorm produced by a line of thunderstorms, capable of straight-line wind damage across a very large area."},{"@type":"DefinedTerm","name":"Disinterested appraiser","description":"An appraiser with no financial or personal stake in the outcome. Many policies require appraisers to be disinterested, impartial or independent."},{"@type":"DefinedTerm","name":"Endorsement","description":"A written change to a policy that adds, removes or modifies coverage, such as a sewer backup endorsement."},{"@type":"DefinedTerm","name":"Estimate review","description":"A line-by-line check of an insurance estimate for missing items, incorrect quantities and pricing that doesn’t reflect local costs."},{"@type":"DefinedTerm","name":"Exclusion","description":"Policy language that removes a cause of loss or type of property from coverage, such as flood or wear and tear."},{"@type":"DefinedTerm","name":"Hail bruising","description":"Damage to a shingle from hail impact that may not be obvious at first glance but can loosen granules and weaken the mat."},{"@type":"DefinedTerm","name":"Holdback","description":"The portion of a replacement cost claim, usually recoverable depreciation, that the insurer withholds until repairs are completed."},{"@type":"DefinedTerm","name":"Ice and water shield","description":"A self-adhering underlayment installed at eaves, valleys and other vulnerable areas to resist leaks from ice dams and wind-driven rain."},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice that forms at a roof’s edge when melting snow refreezes, which can force water under shingles and into the home."},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate describing one task or material with its quantity, unit and price."},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether repaired areas must reasonably match undamaged areas in color, texture or style, and what happens when matching materials aren’t available."},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, such as tarping a roof or drying out a basement. Most policies require it."},{"@type":"DefinedTerm","name":"National Flood Insurance Program","description":"The federal program that provides most flood insurance, which is separate from a standard homeowners policy."},{"@type":"DefinedTerm","name":"Office of the Commissioner of Insurance","description":"Wisconsin’s insurance regulator, known as OCI, which licenses insurers and agents and handles consumer complaints."},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs to bring repaired portions of a building up to current building codes, subject to a limit."},{"@type":"DefinedTerm","name":"Overhead and profit","description":"A general contractor’s charge for business overhead and profit, often a disputed item when several trades are involved."},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible set as a percentage of the dwelling coverage limit rather than a flat dollar amount, often applied to wind or hail losses."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed that some policies require within a set time after a loss or after the insurer’s request."},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation the insurer will pay back once repairs or replacement are completed, under a replacement cost policy."},{"@type":"DefinedTerm","name":"Replacement cost value","description":"The cost to repair or replace damaged property with materials of like kind and quality, without a deduction for depreciation."},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which the insurer continues handling a claim while reserving the right to deny coverage later."},{"@type":"DefinedTerm","name":"Roof square","description":"A unit of roofing measure equal to 100 square feet of roof surface."},{"@type":"DefinedTerm","name":"Scope of loss","description":"The description of what was damaged and what work is needed to repair it, before pricing is applied."},{"@type":"DefinedTerm","name":"Sewer backup endorsement","description":"An optional addition to a homeowners policy that covers water backing up through sewers or drains, or overflowing from a sump, usually up to a separate limit."},{"@type":"DefinedTerm","name":"Snow load","description":"The weight of accumulated snow and ice on a roof, which can cause sagging, cracking or collapse when it exceeds what the structure can carry."},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add or revise items in an insurance estimate after hidden damage is found or omissions are identified."},{"@type":"DefinedTerm","name":"Test square","description":"A marked 10-by-10-foot area on a roof slope used to count hail hits and assess damage."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers can’t agree on."},{"@type":"DefinedTerm","name":"Wisconsin Insurance Plan","description":"Wisconsin’s FAIR plan, offering basic property insurance to owners who can’t obtain it in the regular market."},{"@type":"DefinedTerm","name":"Xactimate","description":"A widely used estimating software platform for property insurance claims, with regional price lists for labor and materials."}],"@id":"https://wisconsininsuranceappraiser.com/claims-dictionary/#definedtermset"}]}</script>
</head>
